// //// Neoffice — added file (no upstream equivalent): the text of src/neoffice/i18nRegistry.ts, from the messages
// //// (scripts/gen-i18n-registry.mjs writes it; src/test/neoffice-i18n.test.ts compares with it).
import { jsString } from '../neoffice-i18n-core.mjs'

export function registrySource(messages) {
  return [
    '// //// Neoffice — added file (no upstream equivalent): GENERATED by scripts/gen-i18n-registry.mjs, do not edit.',
    "// //// Every message that neoffice-i18n.ts asks the catalogue for in Sheets, Slides, Writer and the Drive's pages",
    '// //// (their sources are upstream\'s, without __()), so that the extractor of the translations finds them.',
    '// //// Never called: tree-shaken out of the build. maintenance#1592.',
    '',
    'export function neofficeI18nRegistry(): void {',
    ...messages.map((m) => `  __(${jsString(m)})`),
    '}',
    '',
  ].join('\n')
}
